def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_m, last_o = history[-1]

    if n == 1 and last_m == 'C' and last_o == 'C':
        return 'D'

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1

    coop_rate = opp_c / float(n)

    opp_def_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_def_streak += 1
        i -= 1

    my_def_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_def_streak += 1
        i -= 1

    recent_opp_c = 0
    for _, o in history[-min(5, n):]:
        if o == 'C':
            recent_opp_c += 1

    after_D_C = 0
    after_D_D = 0
    for i in range(1, n):
        prev_m = history[i - 1][0]
        cur_o = history[i][1]
        if prev_m == 'D':
            if cur_o == 'C':
                after_D_C += 1
            else:
                after_D_D += 1

    exploitable = False
    if coop_rate > 0.55 and after_D_C > after_D_D:
        if after_D_C >= 2 or (after_D_C == 1 and after_D_D == 0 and coop_rate > 0.8):
            exploitable = True

    if exploitable:
        return 'D'

    if opp_c == 0 and opp_def_streak >= 2:
        return 'D'

    if n >= 6 and coop_rate <= 0.25:
        return 'D'

    if last_m == 'C' and last_o == 'D':
        if opp_def_streak == 1:
            if coop_rate > 0.55 or opp_c > 0 or n < 5:
                return 'C'
            return 'D'

        if opp_def_streak >= 2:
            if recent_opp_c == 0 and opp_c < n * 0.4:
                return 'D'
            if opp_def_streak >= 6 and recent_opp_c == 0:
                return 'D'
            return 'D'

    if last_m == 'D' and last_o == 'D':
        if opp_def_streak == 4 and my_def_streak >= 2 and recent_opp_c >= 1 and coop_rate > 0.55:
            return 'C'

        if my_def_streak > opp_def_streak and after_D_D >= after_D_C and coop_rate > 0.5 and opp_c > 0:
            return 'C'

        if (
            my_def_streak >= 8
            and opp_def_streak >= 8
            and recent_opp_c == 0
            and opp_c > 0
            and rng.random() < 0.1
        ):
            return 'C'

        return 'D'

    if last_m == 'D' and last_o == 'C':
        if (
            n >= 2
            and history[-2][1] == 'C'
            and after_D_C > 0
            and opp_def_streak == 0
            and coop_rate > 0.65
        ):
            return 'D'

        if recent_opp_c >= 3 and after_D_C > 0 and after_D_D <= after_D_C + 1 and coop_rate > 0.75:
            return 'D'

        return 'C'

    if last_m == 'C' and last_o == 'C':
        if (
            n >= 2
            and history[-2][0] == 'D'
            and history[-1][1] == 'C'
            and opp_def_streak == 0
            and coop_rate > 0.55
        ):
            return 'D'

        return 'C'

    return 'C'
